import { spawn } from "node:child_process";
import { cpSync, readFileSync, rmSync, watch, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..", "..", "..");

const TEMPLATES = [{ src: "apps/template-default", dest: "packages/cli/templates/default" }];

// Files/dirs that are autogenerated, locally-installed, or env-specific.
// Compared against paths relative to the template source root.
const EXCLUDED_PATHS = new Set([
  "node_modules",
  "dist",
  ".output",
  ".tanstack",
  ".nitro",
  ".vinxi",
  ".vite-hooks",
  ".agents",
  ".claude",
  ".env",
  ".env.local",
  ".gitignore",
  "src/routeTree.gen.ts",
  "src/camox/app.ts",
  "src/routes/_camox.tsx",
  "src/routes/_camox",
]);

function syncOne(srcRel, destRel) {
  const src = path.join(REPO_ROOT, srcRel);
  const dest = path.join(REPO_ROOT, destRel);
  rmSync(dest, { recursive: true, force: true });
  cpSync(src, dest, {
    recursive: true,
    filter: (source) => {
      const rel = path.relative(src, source);
      if (!rel) return true;
      return !EXCLUDED_PATHS.has(rel);
    },
  });
  resolveCatalogVersions(path.join(dest, "package.json"));
}

// Reads the default `catalog:` map from pnpm-workspace.yaml. Only flat
// `name: range` entries are supported, which is all the workspace uses.
function readCatalog() {
  const lines = readFileSync(path.join(REPO_ROOT, "pnpm-workspace.yaml"), "utf-8").split("\n");
  const start = lines.indexOf("catalog:");
  if (start === -1) return {};
  const catalog = {};
  for (const line of lines.slice(start + 1)) {
    const match = /^ {2}("?)([^"]+)\1:\s*(.+)$/.exec(line);
    if (!match) break;
    catalog[match[2]] = match[3].trim();
  }
  return catalog;
}

// Scaffolded projects live outside this workspace, so `catalog:` ranges must be
// replaced with the real ones before the template ships.
function resolveCatalogVersions(pkgPath) {
  const catalog = readCatalog();
  const pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
  for (const field of ["dependencies", "devDependencies", "peerDependencies"]) {
    for (const [name, range] of Object.entries(pkg[field] ?? {})) {
      if (range !== "catalog:") continue;
      if (!catalog[name]) throw new Error(`[sync-templates] No catalog entry for "${name}".`);
      pkg[field][name] = catalog[name];
    }
  }
  writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}\n`);
}

function syncAll() {
  for (const { src, dest } of TEMPLATES) {
    syncOne(src, dest);
  }
}

const args = new Set(process.argv.slice(2));
const isWatch = args.has("--watch");
const withBuild = args.has("--build");

syncAll();
console.info(`[sync-templates] Synced ${TEMPLATES.length} template(s).`);

if (withBuild) {
  const child = spawn("vp", ["pack", "--watch"], { stdio: "inherit", shell: false });
  const forward = (sig) => child.kill(sig);
  process.on("SIGINT", forward);
  process.on("SIGTERM", forward);
  child.on("exit", (code) => process.exit(code ?? 0));
}

if (isWatch) {
  let pending = false;
  let timer = null;
  const debounced = () => {
    if (pending) return;
    pending = true;
    clearTimeout(timer);
    timer = setTimeout(() => {
      try {
        syncAll();
        console.info("[sync-templates] Re-synced after change.");
      } catch (err) {
        console.error("[sync-templates] Sync failed:", err);
      } finally {
        pending = false;
      }
    }, 80);
  };

  for (const { src } of TEMPLATES) {
    const srcAbs = path.join(REPO_ROOT, src);
    watch(srcAbs, { recursive: true }, (_event, filename) => {
      if (!filename) return debounced();
      const normalized = filename.split(path.sep).join("/");
      // Skip changes inside excluded paths so we don't churn on autogen files.
      for (const excluded of EXCLUDED_PATHS) {
        if (normalized === excluded || normalized.startsWith(`${excluded}/`)) return;
      }
      debounced();
    });
  }
  console.info("[sync-templates] Watching for changes...");
}
